    ('os-206', 'osmanli-donemi', 'Osmanlı''da "Tersane Amirali" ya da "Kaptan Paşa" olarak bilinen unvan hangi makamı temsil ederdi?', 'Osmanlı Deniz Kuvvetleri Başkomutanı (Kaptan-ı Derya)', ARRAY[]::TEXT[], 'Kaptan-ı Derya, Osmanlı donanmasını komuta eden en üst rütbeli deniz subayıydı.', TRUE, 'medium', 'approved'),
    ('os-207', 'osmanli-donemi', 'Osmanlı''da "Berat" neydi?', 'Padişah tarafından verilen imtiyaz, atama veya hak belgesi', ARRAY[]::TEXT[], 'Berat, ticaret ayrıcalığından dini grup tanınırlığına kadar geniş bir haklar yelpazesini kapsayan resmi belgeydi.', TRUE, 'medium', 'approved'),
    ('os-208', 'osmanli-donemi', 'Osmanlı''nın Akdeniz''de Haçlılara karşı kazandığı büyük deniz zaferlerinden birini kazanan Barbaros Hayreddin Paşa hangi savaşta kesin üstünlük sağlamıştır?', 'Preveze Deniz Muharebesi (1538)', ARRAY[]::TEXT[], 'Preveze''de Osmanlı donanması Avrupa İttifak filosunu dağıtarak Akdeniz hakimiyetini perçinledi.', TRUE, 'medium', 'approved'),
    ('os-209', 'osmanli-donemi', 'Osmanlı''da "Bostancıbaşı" ne işle görevliydi?', 'Saray bahçeleri ve kıyı düzenini koruyan, padişah muhafızlığı da yapan görevli', ARRAY[]::TEXT[], 'Bostancıbaşı saray bahçelerini, köşkleri ve Boğaz kıyılarını denetler; aynı zamanda padişahın kişisel muhafızıydı.', TRUE, 'hard', 'approved'),
    ('os-210', 'osmanli-donemi', 'Osmanlı''nın Rodos''u fetheden padişahı kimdir?', 'Kanuni Sultan Süleyman (1522)', ARRAY[]::TEXT[], 'Kanuni, 1522''de Rodos''u Şövalyelerden alarak Doğu Akdeniz denetimini güçlendirdi.', TRUE, 'medium', 'approved'),
    ('os-211', 'osmanli-donemi', 'Osmanlı''da Topkapı Sarayı''nın ne zaman inşa edildiği ve hangi padişah tarafından yapıldığı nedir?', 'Fatih Sultan Mehmet (1459-1465)', ARRAY[]::TEXT[], 'Fatih Sultan Mehmet İstanbul''un fethinin ardından sarayı Bizans akropolü üzerine inşa ettirdi.', TRUE, 'medium', 'approved'),
    ('os-212', 'osmanli-donemi', 'Osmanlı''da ilk özel Türkçe gazetesi yayımlayan hangi isim öne çıkar?', 'Şinasi ve Agah Efendi – Tercüman-ı Ahval (1860)', ARRAY[]::TEXT[], 'Türk basın tarihinde ilk özel Türkçe gazete olan Tercüman-ı Ahval, 1860''ta yayın hayatına girdi.', TRUE, 'hard', 'approved'),
