    ('os-244', 'osmanli-donemi', 'Osmanlı''da "Tekke" ne işe yarardı?', 'Tarikat mensuplarının ibadet, eğitim ve toplanma mekânı', ARRAY[]::TEXT[], 'Tekkeler, Osmanlı toplumsal ve dini hayatının önemli unsurları olan Sufi tarikatların merkezi konumundaydı.', TRUE, 'medium', 'approved'),
    ('os-245', 'osmanli-donemi', 'Osmanlı''nın Akdeniz''deki en büyük ada olan Kıbrıs''ı fethettiği deniz komutanı kimdir?', 'Lala Mustafa Paşa (1571)', ARRAY[]::TEXT[], 'Lala Mustafa Paşa, II. Selim''in emriyle Kıbrıs seferini yöneterek adayı Venediklilerden aldı.', TRUE, 'medium', 'approved'),
    ('os-246', 'osmanli-donemi', 'Osmanlı''da "Arazi Kanunnamesi" hangi yılda çıkarılmış ve amacı neydi?', '1858 – Arazi mülkiyetini düzenlemek ve tapuya bağlamak', ARRAY[]::TEXT[], '1858 Arazi Kanunnamesi, toprağın özel mülkiyet statüsüne geçişini ve tapu kaydını düzenleyen önemli reformdur.', TRUE, 'hard', 'approved'),
    ('os-247', 'osmanli-donemi', 'Osmanlı''da son halife kimdir ve halifelik ne zaman kaldırılmıştır?', 'Abdülmecid II – 3 Mart 1924', ARRAY[]::TEXT[], 'Türkiye Büyük Millet Meclisi 3 Mart 1924''te hilafetin kaldırılmasına karar verdi; Abdülmecid II sürgüne gönderildi.', TRUE, 'medium', 'approved'),
    ('os-248', 'osmanli-donemi', 'Osmanlı''da Kafkas cephesinde Rusya ile karşılaşılan en büyük felakete yol açan savaş hangisidir?', 'Sarıkamış Harekâtı (1914-1915)', ARRAY[]::TEXT[], 'Enver Paşa''nın yönettiği Sarıkamış Harekâtı kış koşulları ve stratejik hatalar nedeniyle Osmanlı için büyük kayıpla sonuçlandı.', TRUE, 'medium', 'approved'),
    ('os-249', 'osmanli-donemi', 'Osmanlı''nın Anadolu''daki en uzun süre direnen Hristiyan krallığı hangisidir?', 'Trabzon Rum İmparatorluğu (1204-1461)', ARRAY[]::TEXT[], 'Trabzon Rum İmparatorluğu, Konstantinopolis''in Latinlerce işgalinden 1461''deki Osmanlı fethine dek bağımsız kaldı.', TRUE, 'hard', 'approved'),
    ('os-250', 'osmanli-donemi', 'Osmanlı''da "Sicil-i Ahval" ne anlama gelirdi?', 'Devlet memurlarının özlük ve sicil kayıtlarını tutan resmî defter', ARRAY[]::TEXT[], 'Tanzimat''tan sonra oluşturulan Sicil-i Ahval, modern personel yönetiminin Osmanlı versiyonuydu.', TRUE, 'hard', 'approved'),
    ('os-251', 'osmanli-donemi', 'Osmanlı döneminde "Düyun-u Umumiye" ne anlama gelir ve ne zaman kurulmuştur?', 'Genel Borçlar İdaresi – 1881''de alacaklı Avrupalı devletlerce kuruldu', ARRAY[]::TEXT[], 'Osmanlı''nın dış borçlarını yönetmek amacıyla 1881''de kurulan Düyun-u Umumiye yabancıların ekonomik denetimini simgeledi.', TRUE, 'medium', 'approved'),
    ('os-252', 'osmanli-donemi', 'Osmanlı''nın Trablusgarp ve Bingazi''yi yitirdiği antlaşma hangisidir?', 'Uşi Antlaşması (1912)', ARRAY[]::TEXT[], 'Uşi Antlaşması''yla Osmanlı, İtalya''ya Trablusgarp (Libya) ve Onikiadalar''ı bıraktı.', TRUE, 'medium', 'approved'),
    ('os-253', 'osmanli-donemi', 'Osmanlı''da "Divanıhümayun"a sunulan dilekçeye ne denirdi?', 'Arz-ı hal veya arz-ı mahzar', ARRAY[]::TEXT[], 'Halkın padişaha ya da Divan''a sunduğu şikayet ve dilekçeler "arz-ı hal" biçiminde kaleme alınırdı.', TRUE, 'hard', 'approved'),
    ('os-254', 'osmanli-donemi', 'Osmanlı''nın Suriye''ye hakim olmasını sağlayan 1516 savaşı hangisidir?', 'Mercidabık Savaşı', ARRAY[]::TEXT[], 'Yavuz Sultan Selim Mercidabık''ta Memlük kuvvetlerini bozguna uğratarak Suriye ve Filistin''i ele geçirdi.', TRUE, 'medium', 'approved'),
    ('os-255', 'osmanli-donemi', 'Osmanlı''da "Müsellim" ne tür bir görevliydi?', 'Sancak beyi ya da ayanın vekili; idari ve askeri yetkilerle donatılmış yerel temsilci', ARRAY[]::TEXT[], 'Müsellimler özellikle Tanzimat öncesinde bölgesel idarenin alt kademesini oluştururdu.', TRUE, 'hard', 'approved'),
    ('os-256', 'osmanli-donemi', 'Osmanlı döneminde 1475''te Kırım''ı fetheden komutan kimdir?', 'Gedik Ahmet Paşa', ARRAY[]::TEXT[], 'Fatih Sultan Mehmet''in emriyle Gedik Ahmet Paşa Kırım''ı fethederek Ceneviz ve Tatar egemenliğine son verdi.', TRUE, 'hard', 'approved'),
    ('os-257', 'osmanli-donemi', 'Osmanlı''da "Kethüdayeri" ne anlama gelirdi?', 'Sadrazamın vekili ya da iç işler bakanı benzeri yardımcısı', ARRAY[]::TEXT[], 'Kethüdayeri iç güvenlik ve idare işlerini sadrazam adına yürüten üst düzey bürokrat unvanıydı.', TRUE, 'hard', 'approved'),
    ('os-258', 'osmanli-donemi', 'Osmanlı''nın Osmanlı-Rus Savaşı (1768-1774) sonunda imzalanan antlaşma hangisidir?', 'Küçük Kaynarca Antlaşması (1774)', ARRAY[]::TEXT[], 'Küçük Kaynarca Antlaşması Kırım''ın bağımsızlığını ve Rusya''nın Ortodoks Hristiyanlar üzerinde hamiliğini tanıdı.', TRUE, 'medium', 'approved'),
    ('os-259', 'osmanli-donemi', 'Osmanlı''da "Şehir Subaşısı" ne görev yapardı?', 'Şehirde asayişi koruyan ve suçlularla uğraşan güvenlik amiri', ARRAY[]::TEXT[], 'Şehir subaşısı, Osmanlı kentlerinde polis şefi işlevini görürdü; kadıyla işbirliği yapardı.', TRUE, 'hard', 'approved'),
    ('os-260', 'osmanli-donemi', 'Osmanlı''nın son döneminde "Teşkilat-ı Mahsusa" ne amaçla kurulmuştu?', 'Düşman hatları gerisinde özel operasyonlar yürütmek; Balkan Savaşları ve I. Dünya Savaşı''nda', ARRAY[]::TEXT[], 'Teşkilat-ı Mahsusa İttihat ve Terakki Cemiyeti''ne bağlı gizli bir paramiliter örgüttü.', TRUE, 'hard', 'approved'),
    ('os-261', 'osmanli-donemi', 'Osmanlı''da "Siyasi Ajanlar" (Agentler) kimlerdi?', 'İstihbarat ve diplomatik görevler yürüten Osmanlı gizli temsilcileri', ARRAY[]::TEXT[], 'Özellikle II. Abdülhamid döneminde çeşitli ülkelerde görev yapan Osmanlı istihbarat ağı üyeleri bu unvanı taşırdı.', TRUE, 'hard', 'approved'),
    ('os-262', 'osmanli-donemi', 'Osmanlı''nın Irak''ı (Mezopotamya) tamamen kaybettiği I. Dünya Savaşı cephesi hangisidir?', 'Mezopotamya (Irak) Cephesi', ARRAY[]::TEXT[], 'İngiltere, Kut''ül Amare kuşatmasından sonra 1917''de Bağdat''ı ve 1918''de Musul''u alarak Irak''ı ele geçirdi.', TRUE, 'medium', 'approved'),
    ('os-263', 'osmanli-donemi', 'Osmanlı''da "Ehl-i Örf" kimlerdi?', 'Şer''i mahkeme dışında örfi hukukla görev yapan yönetici ve asker sınıfı', ARRAY[]::TEXT[], 'Ehl-i örf; vali, subaşı, sipahi gibi devlet adına ceza ve güvenlik işleri yürüten laikleştirilmiş idari kadroyu oluşturuyordu.', TRUE, 'hard', 'approved'),
    ('os-264', 'osmanli-donemi', 'Osmanlı''da "Çiftlik" hangi düzene girmiş toprak parçasını tanımlardı?', 'Köylü ailesinin geçimini sağlayan standart tarım ünitesi (60-150 dönüm)', ARRAY[]::TEXT[], 'Çiftlik, Osmanlı kırsal ekonomisinde temel üretim birimiydi; tımar ve vergi hesaplamalarında referans ölçüydü.', TRUE, 'hard', 'approved'),
    ('os-265', 'osmanli-donemi', 'Osmanlı''da "Ayan" kimlerdi?', 'Taşrada nüfuz sahibi yerel eşraf ve büyük toprak sahipleri', ARRAY[]::TEXT[], '18.-19. yüzyılda güçlenen ayanlar yerel vergi toplama, asker temin ve yönetim işlerini fiilen üstlendi.', TRUE, 'medium', 'approved'),
    ('os-266', 'osmanli-donemi', 'Osmanlı''da Sened-i İttifak ne zaman imzalanmış ve önemi nedir?', '1808 – II. Mahmut''un ayanlarla imzaladığı ve merkez-taşra dengesini düzenleyen belge', ARRAY[]::TEXT[], 'Sened-i İttifak Osmanlı''nın "Magna Carta"sı olarak anılır; ayan güçlerini tanırken devlet otoritesini de korumayı amaçlar.', TRUE, 'medium', 'approved'),
    ('os-267', 'osmanli-donemi', 'Osmanlı''nın Bosna-Hersek''i kaybetmesine yol açan antlaşma hangisidir?', 'Berlin Antlaşması (1878) – Avusturya-Macaristan''ın yönetimine bırakıldı', ARRAY[]::TEXT[], 'Bosna-Hersek 1908''de Avusturya-Macaristan tarafından resmen ilhak edildi; ama fiili denetim 1878''den beri Avusturya''daydı.', TRUE, 'medium', 'approved'),
    ('os-268', 'osmanli-donemi', 'Osmanlı döneminde "Meclis-i Vükela" ne anlama gelirdi?', 'Bakanlar Kurulu (nazırlar kurulu)', ARRAY[]::TEXT[], 'Tanzimat sonrası oluşturulan Meclis-i Vükela, modern anlamda bakanlar kurulunun Osmanlı karşılığıydı.', TRUE, 'medium', 'approved'),
    ('os-269', 'osmanli-donemi', 'Osmanlı''da "İstimalet" politikası ne anlama gelirdi?', 'Fethedilen ya da müttefik bölge halklarına hoşgörülü ve uzlaşmacı davranma', ARRAY[]::TEXT[], 'İstimalet; yeni alınan yerlerde halkın gönlünü kazanarak direnci kırmayı amaçlayan Osmanlı siyasetidir.', TRUE, 'hard', 'approved'),
    ('os-270', 'osmanli-donemi', 'Osmanlı''da "Mülkname" neydi?', 'Mülkiyet haklarını belgeleyen resmi tapu senedi', ARRAY[]::TEXT[], 'Mülkname veya tapu senedi, özel arazi ve mülklerin yasal sahipliğini ispat eden belgeydi.', TRUE, 'hard', 'approved'),
    ('os-271', 'osmanli-donemi', 'Osmanlı''da II. Meşrutiyet''ten sonra ilan edilen meclisin adı nedir?', 'Meclis-i Mebusan', ARRAY[]::TEXT[], 'Meclis-i Mebusan, 1908''den sonra toplanan ve milletvekillerinden oluşan Osmanlı parlamentosunun alt kanadıdır.', TRUE, 'medium', 'approved'),
    ('os-272', 'osmanli-donemi', 'Osmanlı''da "Kethüda Hatun" ne anlama gelirdi?', 'Haremde valide sultan ya da baş kadın efendinin kayıtlarını tutan kıdemli cariye', ARRAY[]::TEXT[], 'Kethüda Hatun harem yönetiminde sadece valide sultanın altında yer alırdı.', TRUE, 'hard', 'approved'),
    ('os-273', 'osmanli-donemi', 'Osmanlı''da "Çarh-ı Felek" benzetmesi hangi hanedanı kastederek halk edebiyatında kullanılırdı?', 'Genel felekle ilgili olup padişah veya hanedana atıf değil, kaderin döngüselliğini anlatır', ARRAY[]::TEXT[], 'Çarh-ı Felek (dönen felek) Osmanlı ve daha geniş Türk-İran edebiyatında talihin dönüşümünü simgeler.', TRUE, 'hard', 'approved'),
    ('os-274', 'osmanli-donemi', 'Osmanlı''da "Beylerbeyilik" ile "Sancakbeyliği" arasındaki fark nedir?', 'Beylerbeyilik daha büyük bir idari bölge (eyalet), sancakbeyliği bunun alt birimidir', ARRAY[]::TEXT[], 'Beylerbeyi birkaç sancağı yönetirken, sancakbey tek bir sancaktan sorumluydu.', TRUE, 'medium', 'approved'),
    ('os-275', 'osmanli-donemi', 'Osmanlı''da "İmaret" ne işe yarardı?', 'Yoksullara, yolculara ve medrese öğrencilerine ücretsiz yemek dağıtan hayır kurumu', ARRAY[]::TEXT[], 'İmaretler cami-medrese külliyelerinin ayrılmaz parçasıydı ve vakıf gelirleriyle finanse edilirdi.', TRUE, 'medium', 'approved'),
    ('os-276', 'osmanli-donemi', 'Osmanlı''nın Suriye cephesinde Birinci Dünya Savaşı''nda Osmanlı kuvvetleriyle savaşan Arap isyanı kimin liderliğinde başlamıştır?', 'Şerif Hüseyin bin Ali (Mekke Şerifi)', ARRAY[]::TEXT[], 'İngilizlerin teşvik ettiği Arap İsyanı 1916''da Hicaz''da başladı; Lawrence of Arabia bu isyanı destekledi.', TRUE, 'medium', 'approved'),
    ('os-277', 'osmanli-donemi', 'Osmanlı''da "Piyade" ne anlama gelirdi?', 'Yaya asker (piyade sınıfı)', ARRAY[]::TEXT[], 'Piyade, Osmanlı ordusunda at kullanmadan savaşan yaya askerlerden oluşan en temel muharebe sınıfıydı.', TRUE, 'easy', 'approved'),
    ('os-278', 'osmanli-donemi', 'Osmanlı''da I. Dünya Savaşı''ndaki Çanakkale Cephesi''nde Osmanlı savunmasını fiilen yöneten komutan kimdir?', 'Mustafa Kemal (Atatürk)', ARRAY[]::TEXT[], '57. Alay komutanı Mustafa Kemal "Ben size taarruz emretmiyorum, ölmeyi emrediyorum" sözüyle tarihe geçti.', TRUE, 'easy', 'approved'),
    ('os-279', 'osmanli-donemi', 'Osmanlı''da "Zeytinyağı Vergisi" hangi bölgelerde uygulanırdı?', 'Ege, Akdeniz kıyıları ve zeytinliği bol olan bölgeler (Mora, Midilli, Kıbrıs vb.)', ARRAY[]::TEXT[], 'Zeytin üretim bölgelerine özgü bu vergi, Osmanlı tarım vergi sisteminin özelleşmiş bir biçimiydi.', TRUE, 'hard', 'approved'),
    ('os-280', 'osmanli-donemi', 'Osmanlı''da "Hassa Ordusu" ne anlama gelirdi?', 'Padişahı korumakla görevli saray muhafız birlikleri', ARRAY[]::TEXT[], 'Hassa birlikleri, merkez ordusunun özel seçilmiş ve en iyi donatılmış bölükleri olan saray muhafızlarıydı.', TRUE, 'medium', 'approved'),
    ('os-281', 'osmanli-donemi', 'Osmanlı''nın Balkan Savaşları''nda kaybettiği son Avrupa kenti hangisi olmuştur?', 'Edirne (Mayıs 1913, II. Balkan Savaşı''nda geri alındı)', ARRAY[]::TEXT[], 'I. Balkan Savaşı''nda düşen Edirne, II. Balkan Savaşı''nda Osmanlı tarafından yeniden alındı.', TRUE, 'medium', 'approved'),
    ('os-282', 'osmanli-donemi', 'Osmanlı''da "Reisülküttab" ne anlama gelirdi?', 'Osmanlı dışişleri bakanlığı işlevini gören baş kâtip ve protokol şefi', ARRAY[]::TEXT[], 'Reisülküttab, Divan-ı Hümayun''daki yazışma ve diplomatik evrakın baş sorumlusuydu; 18. yüzyıldan sonra dışişleri bakanına dönüştü.', TRUE, 'hard', 'approved'),
    ('os-283', 'osmanli-donemi', 'Osmanlı döneminde "Osmanlı Borsa"sı (Dersaadet Tahvilat Borsası) hangi yılda kurulmuştur?', '1866', ARRAY[]::TEXT[], 'İstanbul''daki Galata bankerlerinin teşvik ettiği borsa 1866''da kurulup Osmanlı menkul kıymet piyasasının çekirdeğini oluşturdu.', TRUE, 'hard', 'approved'),
    ('os-284', 'osmanli-donemi', 'Osmanlı''da "Kıbrıs Problemi"nin başlangıç noktası olarak gösterilen 1878 dönemi olayı nedir?', 'Kıbrıs''ın İngiltere''ye kiralanması (Berlin Kongresi sonrası)', ARRAY[]::TEXT[], '1878''de Berlin Kongresi çerçevesinde Rusya''ya karşı Osmanlı''nın yanında yer alan İngiltere''ye Kıbrıs kiralandı.', TRUE, 'medium', 'approved'),
    ('os-285', 'osmanli-donemi', 'Osmanlı''nın toprak bütünlüğünü korumaya çalışırken "Hasta Adam" lakabını dünyaya kim yaktı?', 'Rusya Çarı I. Nikola (1853)', ARRAY[]::TEXT[], 'Çar I. Nikola, İngiliz Büyükelçisine "Türkiye''yi hasta adam" olarak nitelendirerek parçalanması meselesini gündeme taşıdı.', TRUE, 'medium', 'approved'),
    ('os-286', 'osmanli-donemi', 'Osmanlı''da "Darüşşifa" ne tür bir kurumdu?', 'Hastane (şifa evi)', ARRAY[]::TEXT[], 'Darüşşifalar Osmanlı''da hem tıbbi tedavi hem de akıl hastalıklarının müzik ve su sesiyle tedavisinin yapıldığı kurumdu.', TRUE, 'easy', 'approved'),
    ('os-287', 'osmanli-donemi', 'Osmanlı döneminde "Hamidiye Etfal Hastanesi"ni (Çocuk Hastanesi) kuran padişah kimdir?', 'II. Abdülhamid (1898)', ARRAY[]::TEXT[], 'II. Abdülhamid''in adını taşıyan çocuk hastanesi, Osmanlı''nın modern tıp alanındaki öncü kurumlarındandır.', TRUE, 'medium', 'approved'),
    ('os-288', 'osmanli-donemi', 'Osmanlı''da "Harbiye Nezareti" ne anlama gelirdi?', 'Savaş Bakanlığı (Tanzimat sonrası askeri yönetim bakanlığı)', ARRAY[]::TEXT[], 'Harbiye Nezareti, Osmanlı ordusunun idari ve lojistik işlerini yürüten merkezi bakanlıktı.', TRUE, 'medium', 'approved'),
    ('os-289', 'osmanli-donemi', 'Osmanlı''da "Bahriye Nezareti" ne anlama gelirdi?', 'Deniz Kuvvetleri Bakanlığı', ARRAY[]::TEXT[], 'Bahriye Nezareti, Osmanlı donanmasının yönetiminden sorumlu bakanlıktı.', TRUE, 'medium', 'approved'),
    ('os-290', 'osmanli-donemi', 'Osmanlı döneminde Napolyon''un Mısır''ı işgal etmesi (1798-1801) Osmanlı için ne anlam taşıdı?', 'Osmanlı''nın savunma zafiyetini gösteren ve Avrupa müdahalesine kapı açan kritik kırılma noktası', ARRAY[]::TEXT[], 'Napolyon''un Mısır seferi, Osmanlı''nın askeri modernleşme ihtiyacını ve Batı nüfuzunun artışını somutlaştırdı.', TRUE, 'medium', 'approved'),
    ('os-291', 'osmanli-donemi', 'Osmanlı''nın Mısır''ı Napolyon''dan geri almasında kimin desteği belirleyici olmuştur?', 'İngilizler (İngiltere-Osmanlı ittifakı)', ARRAY[]::TEXT[], 'İngilizler Osmanlı ile ittifak kurarak Fransızları Mısır''dan çıkardı; böylece Doğu Akdeniz''deki dengeyi yeniden kurdu.', TRUE, 'medium', 'approved'),
    ('os-292', 'osmanli-donemi', 'Osmanlı''da "Naib" kimdi?', 'Kadı''nın yokluğunda yerine bakan vekil yargıç', ARRAY[]::TEXT[], 'Naib, kadı hukuku sisteminde ana hâkimin yerini tutan yardımcısı ve vekiliydi.', TRUE, 'hard', 'approved'),
    ('os-293', 'osmanli-donemi', 'Osmanlı''da "Haremeyn" vakıfları ne anlama gelirdi?', 'Mekke ve Medine''nin bakımı için kurulan ve yönetilen vakıflar', ARRAY[]::TEXT[], 'Haremeyn vakıfları Kutsal Şehirlerin altyapısını, hac güzergâhını ve buradaki kurumların finansmanını sağlardı.', TRUE, 'hard', 'approved'),
    ('os-294', 'osmanli-donemi', 'Osmanlı''nın Girit Meselesi hangi uluslararası sonuca yol açmıştır?', 'Girit''in Yunanistan''a katılması (1913, Balkan Savaşları sonrası)', ARRAY[]::TEXT[], 'Ege Adaları meselesinin bir parçası olarak Girit, 1913 Londra Antlaşması''nda Yunanistan''a bırakıldı.', TRUE, 'medium', 'approved'),
    ('os-295', 'osmanli-donemi', 'Osmanlı''da "İklim" terimi idari bağlamda ne anlama gelirdi?', 'Coğrafi bölge ya da büyük idari bölümleme', ARRAY[]::TEXT[], 'İklim, coğrafi veya idari büyük bölgeyi tanımlamak için kullanılan Arapça kökenli Osmanlı terimiydi.', TRUE, 'hard', 'approved'),
    ('os-296', 'osmanli-donemi', 'Osmanlı''da "Muvakkit" ne anlama gelirdi?', 'Cami bünyesinde namaz vakitlerini hesaplayan astronomi uzmanı', ARRAY[]::TEXT[], 'Muvakkitler İslami takvim, ay halleri ve namaz vakitlerini güneş ve yıldız gözlemleriyle belirlerdi.', TRUE, 'hard', 'approved'),
    ('os-297', 'osmanli-donemi', 'Osmanlı''nın "Altın Çağı" olarak değerlendirilen dönemin hükümdarı kimdir?', 'Kanuni Sultan Süleyman (1520-1566)', ARRAY[]::TEXT[], 'Kanuni döneminde Osmanlı''nın en geniş topraklarına ulaştığı, hukuk ve sanat alanlarında doruk noktasına çıkıldığı kabul edilir.', TRUE, 'easy', 'approved'),
    ('os-298', 'osmanli-donemi', 'Osmanlı''da "Nizamname" ne anlama gelirdi?', 'Belirli bir konuyu düzenleyen tüzük ya da yönetmelik', ARRAY[]::TEXT[], 'Tanzimat reformlarıyla birlikte çıkarılan nizamnameler, Osmanlı hukukunda yönetmeliklerin temel biçimiydi.', TRUE, 'medium', 'approved'),
    ('os-299', 'osmanli-donemi', 'Osmanlı''nın Basra Körfezi''ndeki en önemli limanı ve stratejik üssü neresidir?', 'Basra', ARRAY[]::TEXT[], 'Basra, Osmanlı''nın Hint Okyanusu ticaretine açılan kapısı ve güneydeki önemli deniz üssüydü.', TRUE, 'medium', 'approved'),
    ('os-300', 'osmanli-donemi', 'Osmanlı''nın Anadolu''daki en büyük şehri ve ikinci başkenti olarak anılan şehir hangisidir?', 'Bursa', ARRAY[]::TEXT[], 'Osmanlı devletinin kuruluş döneminde Bursa başkent işlevi gördü; Orhan Bey döneminde ilk büyük şehir konumuna geldi.', TRUE, 'easy', 'approved'),
    ('os-301', 'osmanli-donemi', 'Osmanlı''nın Osmanlı-Rus Savaşı 1877-78 sırasında Balkanlar''da geçici olarak tutamadığı ve Rusya''ya kaptırdığı ada hangisidir?', 'Rusya bu savaşta ada değil, Kars, Ardahan, Batum gibi Kafkas toprakları kazandı', ARRAY[]::TEXT[], '1877-78 savaşında Osmanlı Balkanlarda büyük toprak yitirdi; Kars, Ardahan ve Batum Rusya''ya geçti.', TRUE, 'hard', 'approved'),
    ('os-302', 'osmanli-donemi', 'Osmanlı''da "Müderris" unvanının altındaki medrese öğretim derecesi neydi?', 'Danişmend', ARRAY[]::TEXT[], 'Danişmend, medrese hiyerarşisinde müderrisin yardımcısı ve aynı zamanda ders gören öğrenciydi.', TRUE, 'hard', 'approved'),
    ('os-303', 'osmanli-donemi', 'Osmanlı''da "Meclis-i Ahkâm-ı Adliye" ne anlama gelirdi?', 'Tanzimat döneminde kurulan yüksek idare ve hukuk meclisi', ARRAY[]::TEXT[], 'Bu meclis, Osmanlı hukuk reformlarını hazırlamak ve yargı düzenini modernleştirmek amacıyla 1837''de oluşturuldu.', TRUE, 'hard', 'approved'),
    ('os-304', 'osmanli-donemi', 'Osmanlı''da "Serasker" ne anlama gelirdi?', 'Osmanlı''nın başkomutanı; Tanzimat''tan sonra Harbiye Nezareti''yle birleşen askeri mevki', ARRAY[]::TEXT[], 'Serasker, padişah yokken orduyu komuta eden ve Tanzimat''ta Savaş Bakanı''na dönüşen üst rütbeli komutandı.', TRUE, 'medium', 'approved'),
    ('os-305', 'osmanli-donemi', 'Osmanlı''da "Şurâ-yı Devlet" ne işe yarardı?', 'Devlet işlerini danışma kurulu olarak inceleyen Osmanlı Danıştayı', ARRAY[]::TEXT[], 'Fransa''nın Conseil d''État''ından esinlenerek 1868''de kurulan Şurâ-yı Devlet, yasama önerileri ve idari uyuşmazlıkları inceledi.', TRUE, 'hard', 'approved'),
    ('os-306', 'osmanli-donemi', 'Osmanlı döneminde "Koca Ragıp Paşa" neyle tanınmıştır?', 'III. Mustafa dönemi sadrazamı; şair kişiliği ve Ragıp Paşa Kütüphanesi''nin kurucusu', ARRAY[]::TEXT[], 'Koca Ragıp Paşa (ö. 1763) devlet adamlığının yanı sıra divan şairi ve kütüphaneci kimliğiyle Osmanlı kültür hayatına damga vurdu.', TRUE, 'hard', 'approved'),
    ('os-307', 'osmanli-donemi', 'Osmanlı''da "Ferman" neydi?', 'Padişah tarafından çıkarılan ve uyulması zorunlu olan buyruk (emir belgesi)', ARRAY[]::TEXT[], 'Ferman, hukuki düzenlemeden savaş ilanına kadar geniş bir yelpazeyi kapsayan padişah irade belgesidir.', TRUE, 'easy', 'approved'),
    ('os-308', 'osmanli-donemi', 'Osmanlı''nın Kahire''yi fetheden ve Mısır''ı ele geçiren askeri komutanı kimdir?', 'Yavuz Sultan Selim (1517)', ARRAY[]::TEXT[], 'Yavuz Sultan Selim 1517''de Ridaniye Muharebesi''nin ardından Kahire''yi alarak Osmanlı egemenliğini Mısır''a taşıdı.', TRUE, 'easy', 'approved'),
    ('os-309', 'osmanli-donemi', 'Osmanlı döneminde "Mecelle" ne anlama gelirdi?', 'İslam hukukunun (Hanefi fıkhının) Osmanlı tarafından kanunlaştırılmış medeni kanunu', ARRAY[]::TEXT[], 'Ahmet Cevdet Paşa başkanlığındaki komisyon tarafından 1869-1876 arasında hazırlanan Mecelle, sözleşme ve mülkiyet hukukunu düzenledi.', TRUE, 'medium', 'approved'),
    ('os-310', 'osmanli-donemi', 'Osmanlı''da "Osmanlı-Yunan Savaşı" (Doksanüç Harbi değil, 1897 savaşı) nasıl sonuçlandı?', 'Osmanlı galip geldi; Yunanistan tazminat ödedi, ancak Girit özerk statü kazandı', ARRAY[]::TEXT[], '1897 savaşında Osmanlı ordusu Yunanistan''ı yendi; ama Avrupa baskısıyla Girit''e geniş özerklik verildi.', TRUE, 'medium', 'approved'),
    ('os-311', 'osmanli-donemi', 'Osmanlı''nın Üçlü İttifak''a katılmasını konu alan Ekim 1914 tarihi anlaşma ne zaman gerçekleşti?', '29 Ekim 1914 – Osmanlı donanması Karadeniz''de Rusya''ya saldırdı', ARRAY[]::TEXT[], 'Osmanlı''nın Rusya''ya saldırısı I. Dünya Savaşı''na fiilen girişini sağladı; resmi savaş ilanı birkaç gün sonra geldi.', TRUE, 'medium', 'approved'),
    ('os-312', 'osmanli-donemi', 'Osmanlı''da "İpek Yolu" kontrolü açısından hangi kentler stratejikti?', 'Bursa, İstanbul, Halep, Şam, Bağdat', ARRAY[]::TEXT[], 'Bu kentler, Asya''dan Avrupa''ya uzanan transit ticaret güzergâhının kritik durakları ve Osmanlı gümrük gelirinin kaynakları oldu.', TRUE, 'medium', 'approved'),
    ('os-313', 'osmanli-donemi', 'Osmanlı döneminde Galata bankerlerinin önemi neydi?', 'Sarraf ve banker olarak Osmanlı''ya kredi sağlamak ve para işlemlerini yürütmek', ARRAY[]::TEXT[], 'Galata bankerleri çoğunlukla Rum, Ermeni ve Yahudi toplumundan gelirdi; Osmanlı finansmanında merkezi rol oynadı.', TRUE, 'medium', 'approved'),
    ('os-314', 'osmanli-donemi', 'Osmanlı''da "Acemi Oğlanı Ocağı" ne anlama gelirdi?', 'Devşirme kökenli gençlerin yeniçeri öncesi eğitim gördüğü askeri okul', ARRAY[]::TEXT[], 'Acemi oğlanları, Topkapı Sarayı ve büyük çiftliklerde eğitim aldıktan sonra yeniçeri ocağına seçilirdi.', TRUE, 'medium', 'approved'),
    ('os-315', 'osmanli-donemi', 'Osmanlı''nın Kuzey Afrika''yı yönetme biçimi ne olmuştur?', 'Eyaletler aracılığıyla (Mısır, Trablusgarp, Tunus, Cezayir); taşradaki askeri yöneticilerle', ARRAY[]::TEXT[], 'Kuzey Afrika eyaletleri özgün yerel yapılarını korurken Osmanlı üstünlüğünü tanıyan yarı özerk yönetimler geliştirdi.', TRUE, 'medium', 'approved'),
    ('os-316', 'osmanli-donemi', 'Osmanlı''da "Askerî İdadi" ne anlama gelirdi?', 'Subay adaylarına lise düzeyi eğitim veren askeri okul', ARRAY[]::TEXT[], 'Askeri idadiler, Harbiye''ye giden subay adaylarının hazırlandığı orta öğretim kurumlarıydı.', TRUE, 'hard', 'approved'),
    ('os-317', 'osmanli-donemi', 'Osmanlı''da II. Meşrutiyet dönemi İttihatçı üçlüsü kimlerdir?', 'Enver Paşa, Talat Paşa ve Cemal Paşa', ARRAY[]::TEXT[], '1913''ten sonra Osmanlı''yı fiilen yöneten bu üç İttihatçı, I. Dünya Savaşı''na girme kararını verdiler.', TRUE, 'medium', 'approved'),
    ('os-318', 'osmanli-donemi', 'Osmanlı döneminde Midhat Paşa kimdir ve neden önemlidir?', 'Tanzimat devlet adamı ve Kanun-i Esasi''nin (1876 Anayasası) mimarı', ARRAY[]::TEXT[], 'Midhat Paşa, anayasal monarşi ve parlamentarizmin Osmanlı''daki en önemli savunucusuydu.', TRUE, 'medium', 'approved'),
    ('os-319', 'osmanli-donemi', 'Osmanlı''da "Şeriat" ve "Kanun" arasındaki fark neydi?', 'Şeriat, İslami dini hukuktu; Kanun, padişahın çıkardığı laik-örfi hukuktu', ARRAY[]::TEXT[], 'Osmanlı''da şeriat ve örfi (padişah) hukuku iç içe geçerdi; Kanunname-i Âl-i Osman bu ikiliği düzenledi.', TRUE, 'medium', 'approved'),
    ('os-320', 'osmanli-donemi', 'Osmanlı''nın İstanbul''u fethinden sonra imzaladığı ilk büyük ticaret antlaşması hangi ülkeyledir?', 'Venedik Cumhuriyeti (1454)', ARRAY[]::TEXT[], 'Fatih Sultan Mehmet, İstanbul''un fethinin hemen ardından Venedik ile ticaret antlaşması imzaladı.', TRUE, 'hard', 'approved'),
    ('os-321', 'osmanli-donemi', 'Osmanlı''da padişahlar Cuma namazını hangi camide kılardı?', 'Selamlık töreniyle Cuma namazlarında farklı camilere giderlerdi; genellikle saray yakınındaki selatin camileri', ARRAY[]::TEXT[], 'Padişah cuma alayı (selamlık) büyük bir törenle gerçekleşir; farklı dönemlerde farklı selatin camileri kullanılırdı.', TRUE, 'hard', 'approved'),
    ('os-322', 'osmanli-donemi', 'Osmanlı''da "Nişancı" hangi devlet görevini üstlenirdi?', 'Padişah tuğrasını belgelere basan ve kanunnameleri hazırlayan şansölye', ARRAY[]::TEXT[], 'Nişancı, padişah tuğrasını çizmek ve resmi belgelere basmakla yükümlü Divan-ı Hümayun''un önemli üyesiydi.', TRUE, 'hard', 'approved'),
    ('os-323', 'osmanli-donemi', 'Osmanlı''da "Padişah sarayının" hazinesinden ayrı tutulan ve Osmanlı devletinin resmi hazinesi nerede saklanırdı?', 'Hazine-i Amire – başlangıçta Topkapı Sarayı''nda, sonra ayrı bir yapıda', ARRAY[]::TEXT[], 'Osmanlı devlet hazinesi (Hazine-i Amire), padişahın özel iç hazinesinden (Hazine-i Hümayun) ayrı tutulurdu.', TRUE, 'hard', 'approved'),
    ('os-324', 'osmanli-donemi', 'Osmanlı''da "Mihmandar" ne anlama gelirdi?', 'Yabancı devlet elçilerine veya önemli konuklara eşlik eden ve ağırlayan resmi görevli', ARRAY[]::TEXT[], 'Mihmandar, diplomatik protokol gereği yabancı elçileri İstanbul''a girişten görev bitimine kadar refakat ederdi.', TRUE, 'hard', 'approved'),
    ('os-325', 'osmanli-donemi', 'Osmanlı''da "Sadaret Kaymakamı" ne anlama gelirdi?', 'Sadrazam seferdeyken ya da makam boşken vekillik yapan görevli', ARRAY[]::TEXT[], 'Sadrazam''ın yokluğunda başkenti idare eden Sadaret Kaymakamı, sadrazam vekili işlevi gördü.', TRUE, 'hard', 'approved'),
    ('os-326', 'osmanli-donemi', 'Osmanlı''da "Taşra" ile "Merkez" arasındaki temel gerilim ne üzerinde yoğunlaşırdı?', 'Vergi toplama, asker temini ve yerel özerklik ile merkezi denetim çatışması', ARRAY[]::TEXT[], 'Ayan ve bölgesel güçlerin merkezi otorite karşısındaki direnci Osmanlı''nın temel siyasi gerilimini oluşturuyordu.', TRUE, 'medium', 'approved'),
    ('os-327', 'osmanli-donemi', 'Osmanlı''da "Enderun''un birinci odası" hangisiydi?', 'Büyük Oda (Büyük Odabalılar)', ARRAY[]::TEXT[], 'Enderun''daki odalar hiyerarşisi: Küçük Oda, Büyük Oda, Doğancılar, Seferli, Kilerli, Hazine ve Has Oda''dan oluşurdu.', TRUE, 'hard', 'approved'),
    ('os-328', 'osmanli-donemi', 'Osmanlı''da "Celep" ne anlama gelirdi?', 'Hayvan ticareti yapan ya da devlete hayvan temin eden tüccar', ARRAY[]::TEXT[], 'Celepkeşan, ordunun et ihtiyacını karşılamak üzere devlet adına büyükbaş hayvan temin ederdi.', TRUE, 'hard', 'approved'),
    ('os-329', 'osmanli-donemi', 'Osmanlı''da "Hatt-ı Şerif" ile "Hatt-ı Hümayun" arasındaki fark nedir?', 'İkisi de padişah buyruğudur; Hatt-ı Şerif daha kısa ve günlük işleri, Hatt-ı Hümayun daha kapsamlı devlet kararlarını içerirdi', ARRAY[]::TEXT[], 'Hatt-ı Şerif genellikle Divan belgelerinin kenar notuyken, Hatt-ı Hümayun resmi ferman niteliğindeydi.', TRUE, 'hard', 'approved'),
    ('os-330', 'osmanli-donemi', 'Osmanlı''da "Kadın Efendi" unvanı kime verilirdi?', 'Padişahın eş statüsündeki başlıca cariyelerine (hasekilerden sonra gelen)', ARRAY[]::TEXT[], 'Kadın efendiler haremde hiyerarşik sıraya göre birinci, ikinci, üçüncü ve dördüncü kadın olarak anılırdı.', TRUE, 'medium', 'approved'),
    ('os-331', 'osmanli-donemi', 'Osmanlı''nın "Ordu-yu Hümayun" terimi ne anlama gelirdi?', 'Padişahın ordusunu oluşturan tüm askeri birlikler (hümayun = padişaha ait)', ARRAY[]::TEXT[], 'Ordu-yu Hümayun, Osmanlı''nın en büyük sefere çıktığında padişah komutasında toplanan kara ve denizkuvvetleri anlamına gelirdi.', TRUE, 'medium', 'approved'),
    ('os-332', 'osmanli-donemi', 'Osmanlı''da "Cizye" vergisi hangi padişah döneminde fiilen kaldırılmıştır?', 'Abdülmecid I – Tanzimat Fermanı (1856 Islahat Fermanı) döneminde', ARRAY[]::TEXT[], '1856 Islahat Fermanı gayrimüslimleri cizye''den muaf tutarak onları diğer vatandaşlarla eşit saydı.', TRUE, 'medium', 'approved'),
    ('os-333', 'osmanli-donemi', 'Osmanlı''nın Anadolu''daki ilk başkenti neresidir?', 'Söğüt (İlk merkez) ve ardından Bursa (1326)', ARRAY[]::TEXT[], 'Osmanlı beyliği Söğüt''te kuruldu; Bursa''nın fethiyle birlikte şehir Osmanlı''nın ilk gerçek başkenti haline geldi.', TRUE, 'easy', 'approved'),
    ('os-334', 'osmanli-donemi', 'Osmanlı''da "Fetret Devri" hangi tarihleri kapsar ve neden bu ad verilmiştir?', '1402-1413 – Bayezid''in esir alınmasından Mehmet I''in iktidarı yeniden toparlamasına dek süren otorite boşluğu', ARRAY[]::TEXT[], 'Ankara Savaşı''nın ardından Osmanlı şehzadeler arasında taht kavgasına sahne oldu; bu döneme "fetret = duraklama" adı verildi.', TRUE, 'medium', 'approved'),
    ('os-335', 'osmanli-donemi', 'Osmanlı''da "Oğuz" boylarına ait olduğunu iddia eden ilk Osmanlı belgeleri hangi dönemden kalmadır?', 'Fatih Sultan Mehmet sonrası dönem (15. yüzyıl)', ARRAY[]::TEXT[], 'Osmanlıların Oğuz Han''a kadar uzanan soy iddialarını belgeleyen tarihnameler 15. yüzyıldan itibaren yaygınlaştı.', TRUE, 'hard', 'approved'),
    ('os-336', 'osmanli-donemi', 'Osmanlı''da Anadolu ve Rumeli''yi birbirine bağlayan boğaz geçişini kimin kontrol ettiği stratejik öneme sahipti. Boğazlara hâkim olmak için inşa edilen kaleler hangileridir?', 'Rumeli Hisarı ve Anadolu Hisarı (Fatih döneminde İstanbul kuşatması öncesi)', ARRAY[]::TEXT[], 'Fatih, 1452''de Rumeli Hisarı''nı inşa ederek İstanbul''u tümüyle ablukaya aldı; Anadolu Hisarı ise I. Bayezid döneminden kalmadır.', TRUE, 'medium', 'approved'),
    ('os-337', 'osmanli-donemi', 'Osmanlı''da "İhtisap" (şehir zabıtası) ne tür bir görev yapardı?', 'Çarşı denetimi, fiyat kontrolü ve esnafın ahlak kurallarına uymasını sağlamak', ARRAY[]::TEXT[], 'Muhtesib (ihtisap amiri), pazarlarda kalite denetimi yapar, teraziyi kontrol eder ve haksız fiyata ceza verirdi.', TRUE, 'medium', 'approved'),
    ('os-338', 'osmanli-donemi', 'Osmanlı''nın Avusturya ile imzaladığı ve Viyana''ya ulaşmadan geri çekildiği dönemi kapatan önemli antlaşma hangisidir?', 'Karlofça Antlaşması (1699)', ARRAY[]::TEXT[], 'Kutsal İttifak''a karşı alınan yenilgilerin ardından Osmanlı, II. Viyana Kuşatması sonrasında Avusturya''ya büyük toprak verdi.', TRUE, 'medium', 'approved'),
    ('os-339', 'osmanli-donemi', 'Osmanlı''da "Hatt-ı Hümayun" belgelerini hazırlayan divan kalemine ne denirdi?', 'Divan-ı Hümayun Kalemi', ARRAY[]::TEXT[], 'Divan kalemi, bütün resmi yazışmaları düzenleyen ve tuğra yazısı konusunda uzman kâtipler yetiştiren bürodur.', TRUE, 'hard', 'approved'),
    ('os-340', 'osmanli-donemi', 'Osmanlı''da "Gülhane Hatt-ı Hümayunu" hangi fermanı ifade eder?', 'Tanzimat Fermanı (3 Kasım 1839)', ARRAY[]::TEXT[], 'Gülhane Hatt-ı Hümayunu olarak da bilinen Tanzimat Fermanı, Gülhane Parkı''nda okunduğundan bu adı almıştır.', TRUE, 'medium', 'approved'),
    ('os-341', 'osmanli-donemi', 'Osmanlı''da "Mutasarrıf" ne anlama gelirdi?', 'Sancak yöneticisi (sancak beyi''nin daha geç dönemdeki unvanı)', ARRAY[]::TEXT[], 'Tanzimat sonrasında sancak beyi yerine mutasarrıf unvanı kullanılmaya başlandı.', TRUE, 'medium', 'approved'),
    ('os-342', 'osmanli-donemi', 'Osmanlı''nın kısa süre tahtta kaldığı padişahlar arasında en az on gün hüküm süren hangisidir?', 'IV. Mustafa (yaklaşık 1 yıl, 1807-1808)', ARRAY[]::TEXT[], 'IV. Mustafa, III. Selim''in devrilmesiyle tahta çıktı; kısa süren iktidarından sonra öldürüldü.', TRUE, 'hard', 'approved'),
    ('os-343', 'osmanli-donemi', 'Osmanlı''da "Mahkeme-i Nizamiye" ne anlama gelirdi?', 'Tanzimat''tan sonra kurulan laik (nizami) mahkemeler', ARRAY[]::TEXT[], 'Nizamiye mahkemeleri, şer''iye mahkemelerinin yanı sıra ticaret ve ceza hukukuna bakarak Osmanlı yargı sistemini ikili hale getirdi.', TRUE, 'medium', 'approved'),
    ('os-344', 'osmanli-donemi', 'Osmanlı''nın Arap İsyanı sırasında (1916-1918) T.E. Lawrence (Lawrence of Arabia) kimin adına hareket ediyordu?', 'İngiliz kuvvetleri adına; Şerif Hüseyin liderliğindeki Arap kuvvetlerine danışmanlık yapıyordu', ARRAY[]::TEXT[], 'Lawrence, Osmanlı''ya karşı Arap isyanını organize eden İngiliz istihbarat subayıydı.', TRUE, 'medium', 'approved'),
    ('os-345', 'osmanli-donemi', 'Osmanlı''da "Şehnameci" ne yapardı?', 'Padişahın faaliyetlerini anlatan ve resmi tarihi yazan saray vakanüvisi', ARRAY[]::TEXT[], 'Şehnameci, Farsça şehname geleneğinden beslenerek padişahın zaferlerini manzum veya mensur olarak kayıt altına alırdı.', TRUE, 'hard', 'approved'),
    ('os-346', 'osmanli-donemi', 'Osmanlı''da "Daru''l-Hadis" ne anlama gelirdi?', 'Hz. Peygamber''in hadislerinin öğretildiği özelleşmiş medrese', ARRAY[]::TEXT[], 'Darü''l-Hadis, Osmanlı''da hadis bilimine özgü olarak kurulan en üst düzey dini eğitim kurumlarından biriydi.', TRUE, 'hard', 'approved'),
    ('os-347', 'osmanli-donemi', 'Osmanlı''da "Osmanlı Anayasası" (Kanun-i Esasi) kaç yıl yürürlükte kalmıştır?', 'Yaklaşık 1 yıl fiilen (1876-1878), ardından II. Meşrutiyet''te yeniden (1908-1920)', ARRAY[]::TEXT[], 'II. Abdülhamid 1878''de meclisi kapattı; anayasa askıya alındı. 1908''de İTC baskısıyla yeniden işleme girdi.', TRUE, 'medium', 'approved'),
    ('os-348', 'osmanli-donemi', 'Osmanlı''da "Muhasebe Kalemi" ne işe yarardı?', 'Osmanlı devlet gelir-giderlerini tutan merkezi muhasebe birimi', ARRAY[]::TEXT[], 'Muhasebe Kalemi, Osmanlı maliyesinin kayıt ve denetimini üstlenen temel idari birimdi.', TRUE, 'hard', 'approved'),
    ('os-349', 'osmanli-donemi', 'Osmanlı''da "Araplara özgü" sayılan ve Şam, Halep, Kahire gibi şehirlerde uygulanan idari düzenleme hangisiydi?', 'Genel olarak eyalet sistemi; ancak Mısır yarı özerk Hidiv yönetimi, Hicaz ise Şerif yönetimindeydi', ARRAY[]::TEXT[], 'Osmanlı Arap eyaletlerinde tek tip bir yönetim yerine bölgesel koşullara göre farklı idari çözümler uygulandı.', TRUE, 'hard', 'approved'),
    ('os-350', 'osmanli-donemi', 'Osmanlı İmparatorluğu''nun toprak bütünlüğünü ve bağımsızlığını güvence altına alan en son uluslararası antlaşma hangisidir?', 'Berlin Antlaşması (1878)', ARRAY[]::TEXT[], 'Büyük güçlerin Osmanlı toprak bütünlüğünü resmi düzeyde son kez güvence altına aldığı antlaşma Berlin''de imzalandı.', TRUE, 'medium', 'approved'),
    ('os-351', 'osmanli-donemi', 'Osmanlı''da "Devlet-i Aliyye" ne anlama gelirdi?', 'Osmanlı Devleti''nin resmi tam adı (Yüce Devlet)', ARRAY[]::TEXT[], '"Devlet-i Aliyye-i Osmaniyye" Osmanlı imparatorluğunun resmi adıydı; yabancı yazışmalarda bu isim kullanılırdı.', TRUE, 'easy', 'approved'),
    ('os-352', 'osmanli-donemi', 'Osmanlı''da "Manevi Güç" kaynağı sayılan ve Hz. Peygamber''e ait olduğuna inanılan en değerli emanetler nerede korunurdu?', 'Topkapı Sarayı''ndaki Mukaddes Emanetler Dairesi', ARRAY[]::TEXT[], 'Hırka-i Saadet Dairesi''nde Peygamber''in hırkası, kılıcı, mühürleri gibi kutsal emanetler korunmaktadır.', TRUE, 'medium', 'approved'),
    ('os-353', 'osmanli-donemi', 'Osmanlı''da "Osmanlıcılık" ideolojisi ne anlama gelirdi?', 'Etnik ve dini farklılıkları aşarak tüm Osmanlı vatandaşlarını ortak bir kimlikte birleştirme ülküsü', ARRAY[]::TEXT[], 'Tanzimat döneminde geliştirilen Osmanlıcılık; milliyetçi hareketlere karşı imparatorluk birliğini korumayı hedefledi.', TRUE, 'medium', 'approved'),
    ('os-354', 'osmanli-donemi', 'Osmanlı''da "Türkçülük" akımı hangi döneme denk gelir?', 'Geç 19. yüzyıl ve II. Meşrutiyet sonrası (1908+)', ARRAY[]::TEXT[], 'Türk milliyetçiliği Ziya Gökalp gibi düşünürlerin öncülüğünde II. Meşrutiyet döneminde belirgin bir ideoloji hâline geldi.', TRUE, 'medium', 'approved'),
    ('os-355', 'osmanli-donemi', 'Osmanlı''nın son kez Kudüs''ü İngilizlere kaptırdığı tarih ne zamandır?', 'Aralık 1917 – General Allenby''nin girişiyle', ARRAY[]::TEXT[], 'İngiliz General Allenby 9 Aralık 1917''de Kudüs''e girdi; böylece 400 yıllık Osmanlı yönetimi sona erdi.', TRUE, 'medium', 'approved'),
    ('os-356', 'osmanli-donemi', 'Osmanlı''da "Kazasker" ne anlama gelirdi?', 'Osmanlı ordusunda yargı ve dini işlerden sorumlu üst yargıç (kadı askeri)', ARRAY[]::TEXT[], 'Rumeli ve Anadolu Kazaskerleri Osmanlı ilmiye sınıfının en üst makamlarından birini temsil ederdi.', TRUE, 'hard', 'approved'),
    ('os-357', 'osmanli-donemi', 'Osmanlı''da "Mülkiyet Belgesi" anlamına gelen tapu senedinin resmi adı neydi?', 'Tapu senedi (Temlik belgesi de denilebilir)', ARRAY[]::TEXT[], 'Osmanlı tapu sistemi, 1858 Arazi Kanunnamesi ile modernize edilerek mülkiyet hakları belgeye bağlandı.', TRUE, 'medium', 'approved'),
    ('os-358', 'osmanli-donemi', 'Osmanlı''da II. Abdülhamid döneminin "Pan-İslamizm" politikası ne anlama gelirdi?', 'Dünya Müslümanlarını halifelik sembolü etrafında siyasi birlik içinde toplamayı amaçlayan dış politika', ARRAY[]::TEXT[], 'II. Abdülhamid, halife kimliğini yurt içi meşruiyet ve dış politika için etkin biçimde kullandı.', TRUE, 'medium', 'approved'),
    ('os-359', 'osmanli-donemi', 'Osmanlı''da "Divanı Harp" ne anlama gelirdi?', 'Askeri mahkeme (savaş divanı)', ARRAY[]::TEXT[], 'Divan-ı Harp, askeri suçları yargılayan ve I. Dünya Savaşı sonrasında savaş suçlularını yargılayan mahkemeydi.', TRUE, 'medium', 'approved'),
    ('os-360', 'osmanli-donemi', 'Osmanlı''nın şeker, kahve ve tütün ticaretini ne zaman ve nasıl düzenledi?', 'Tekel (inhisar) sistemiyle; özellikle tütün tekeli 19. yüzyılda Düyun-u Umumiye''ye bırakıldı', ARRAY[]::TEXT[], 'Kahve, tütün ve şeker gibi mallar Osmanlı''da çeşitli dönemlerde tekel ve vergilendirme politikasına tabi tutuldu.', TRUE, 'hard', 'approved'),
    ('os-361', 'osmanli-donemi', 'Osmanlı''da "Yeniçeri İsyanları" neden sık görülürdü?', 'Maaşların gecikmesi, maaşların bakırla ödenmesi, sefere çıkarılmak istenmeme ve siyasi müdahale hırsı', ARRAY[]::TEXT[], 'Yeniçeriler iktisadi çıkar ve siyasi güçlerini korumak için tarihte 30''dan fazla isyan gerçekleştirdi.', TRUE, 'medium', 'approved'),
    ('os-362', 'osmanli-donemi', 'Osmanlı''da "Süreli yayın" anlamındaki "periyodik gazete"nin ilki olan Takvim-i Vekayi''yi çıkaran II. Mahmut bu girişimle neyi amaçladı?', 'Resmi Osmanlı haberlerini ve fermanlarını halka ve yetkililere hızla iletmek', ARRAY[]::TEXT[], 'İlk Türkçe resmi gazete, 1831''de II. Mahmut döneminde kamuoyunu yönlendirme amacıyla kuruldu.', TRUE, 'medium', 'approved'),
    ('os-363', 'osmanli-donemi', 'Osmanlı''da "Orta Anadolu" denen bölgenin tarımsal açıdan en önemli ürünü neydi?', 'Buğday ve arpa (tahıl)', ARRAY[]::TEXT[], 'İç Anadolu''nun geniş düzlükleri tarım boyunca tahıl üretiminin merkezi olup Osmanlı''nın gıda güvencesinde kritik rol oynadı.', TRUE, 'medium', 'approved'),
    ('os-364', 'osmanli-donemi', 'Osmanlı''da "Osmanlı-İran Savaşı 1821-23" hangisiyle sonuçlandı?', 'Erzurum Antlaşması (1823) – sınırlar korundu', ARRAY[]::TEXT[], 'Osmanlı-İran savaşı, Osmanlı kuvvetlerinin Bağdat ve Musul''u savunmasıyla 1823''te Erzurum Antlaşması''yla son buldu.', TRUE, 'hard', 'approved'),
    ('os-365', 'osmanli-donemi', 'Osmanlı''da "Levend" kimlerdi?', 'Düzensiz, işsiz asker; bazen deniz kuvvetlerinde görev alan serbest savaşçı', ARRAY[]::TEXT[], 'Leventler, tımar sisteminden taşan, düzenli ordu dışında kalan ve toplumsal huzursuzluk yaratan aylak askerlerdi.', TRUE, 'hard', 'approved'),
    ('os-366', 'osmanli-donemi', 'Osmanlı''nın sahip olduğu en geniş topraklar hangi padişah döneminde ve yaklaşık kaç km²''dir?', 'Kanuni Sultan Süleyman dönemi – yaklaşık 14,9 milyon km²', ARRAY[]::TEXT[], '16. yüzyılın ortasında Osmanlı, üç kıtada yaklaşık 15 milyon km²''lik alana yayılmıştı.', TRUE, 'medium', 'approved'),
    ('os-367', 'osmanli-donemi', 'Osmanlı''da "Padişah Hasan Paşa" (Cezayirli Hasan Paşa) neyle ünlüdür?', 'Osmanlı donanmasını toparlamaya çalışan ve kölelikten yükselerek Kaptan-ı Deryalığa ulaşan denizci', ARRAY[]::TEXT[], 'Cezayirli Hasan Paşa, İnebahtı yenilgisinin ardından Osmanlı donanmasını yeniden örgütleyen önemli bir deniz komutanıydı.', TRUE, 'hard', 'approved'),
    ('os-368', 'osmanli-donemi', 'Osmanlı''da "Saray Kadınlar Saltanatı" (Kadınlar Saltanatı) hangi dönemi kapsar?', 'Yaklaşık 1533-1656 (Hürrem Sultan''dan Köprülüler''in iktidarına kadar)', ARRAY[]::TEXT[], 'Saray kadınlarının (valide sultan ve hasekiler) siyasi etkisinin zirveye çıktığı bu dönem 17. yüzyılda sona erdi.', TRUE, 'medium', 'approved'),
    ('os-369', 'osmanli-donemi', 'Osmanlı''da "Defterdar" ne anlama gelirdi?', 'Osmanlı hazinesi ve maliyesinden sorumlu üst düzey görevli (hazine bakanı)', ARRAY[]::TEXT[], 'Defterdar, Osmanlı devlet gelir-giderlerini denetleyen ve Divan-ı Hümayun''un önemli üyelerinden biriydi.', TRUE, 'medium', 'approved'),
    ('os-370', 'osmanli-donemi', 'Osmanlı''nın Balkanlar''daki dini müesseseleri yaygınlaştırma politikasının en somut örneği nedir?', 'Cami, tekke ve medreselerin Balkan şehirlerinde inşa edilmesi', ARRAY[]::TEXT[], 'Osmanlı fetihlerinin ardından Sofya, Üsküp, Selanik gibi şehirlerde kitlesel cami ve medrese inşaatı başladı.', TRUE, 'medium', 'approved'),
    ('os-371', 'osmanli-donemi', 'Osmanlı döneminde "Kızılbaş" terimi kimi tanımladı?', 'Safevi yanlısı Alevi-Türkmen grupları (Osmanlı''da siyasi bir tehdit olarak algılandılar)', ARRAY[]::TEXT[], 'Kızılbaş, kırmızı başlıklı Safevi taraftarlarını tanımladı; Osmanlı bu terimi rakip ve tehlikeli gruplar için kullandı.', TRUE, 'medium', 'approved'),
    ('os-372', 'osmanli-donemi', 'Osmanlı''da "Osmanlı-Avusturya Savaşları" dönemi ne zaman sona erdi?', '1791 – Ziştovi Antlaşması', ARRAY[]::TEXT[], 'Osmanlı-Avusturya Savaşları, Viyana kuşatmalarından (1683) başlayıp 1791 Ziştovi Antlaşması''yla son büyük savaşı kapattı.', TRUE, 'hard', 'approved'),
    ('os-373', 'osmanli-donemi', 'Osmanlı''da "Bozoklar" (Sağkol) ile "Üçoklar" (Solkol) ne anlama gelirdi?', 'Orta Asya kökenli Oğuz Türkmen boylarını iki ana gruba ayıran bölünme', ARRAY[]::TEXT[], 'Bozok ve Üçok, Orta Asya Türk boy sisteminin iki büyük kanat kolunu temsil ederdi; Osmanlı da Oğuz geleneğini benimsedi.', TRUE, 'hard', 'approved'),
