-- Verify count
DO $$
DECLARE
    v_total INTEGER;
    v_active INTEGER;
BEGIN
    SELECT count(*), count(*) FILTER (WHERE is_active)
    INTO v_total, v_active
    FROM public.questions;

    RAISE NOTICE 'Total questions in DB: %, Active: %', v_total, v_active;
END;
$$;
